roc.top_vis	equ param+4	200 $C8 Top visible window set by find_top call.boxflag	equ top_vis+4	204 $CC 0 = close, 1 = zoom.old_port	equ boxflag+2	206 $CE Original port on entry.save_cnt	equ old_port+4	208 $D0 Counter for save port.FloorRgn	equ save_cnt+2	212 $D4 Desktop region less windows above.data	equ FloorRgn+4	216 $D8 Pointer to data area.MyID	equ data+4	220 $DC Memory ID number.work	equ MyID+2	222 $DE Work area. (ONLY 12 BYTES? GrowWindow seems to use the most --DAL 19-Jan-91)AuxInfoHandle	equ work+12	230 $EA handle to auxiliary window info block (DAL);; --- Tool call function numbers ------------------------------;GetNextEvent	equ $0A06EventAvail	equ $0B06UnionRgn	equ $7204DiffRgn	equ $7304;;; --- RECT record offsets --------------------------------------;y1	equ 0x1	equ y1+2y2	equ x1+2x2	equ y2+2RECTSIZE	equ x2+2;;; --- Offset into GrafPort Record ------------------------------;GP_PortInfo	equ 0GP_Bounds	equ GP_PortInfo+8GP_PortRect	equ GP_Bounds+8GP_ClipRgn	equ GP_PortRect+8GP_VisRgn	equ GP_ClipRgn+4GP_BkPat	equ GP_VisRgn+4;;; --- Paint Pixels parameter block -----------------------------;PP_SrcInfo	equ 0PP_DesInfo	equ PP_SrcInfo+4PP_SrcRect	equ PP_DesInfo+4PP_DesRect	equ PP_SrcRect+4PP_Mode	equ PP_DesRect+4PP_Clip	equ PP_Mode+2;;; --- LocInfo record -------------------------------------------;PortSCB	equ 0PixelImage	equ PortSCB+2Width	equ PixelImage+4PBounds	equ Width+2LOCINFO	equ PBounds+8;;; --- Region record	--------------------------------------------;Rgn_Len	equ 0Rgn_Bounds	equ Rgn_Len+2;;; --- Desk pattern message record offsets.;messNext	equ 0	DeskMessage record offsets.messType	equ messNext+4messFormat	equ messType+2	0=pattern, 1=picture.messInfo	equ messFormat+2	Pattern or picture data.;;; --- Task record offsets --------------------------------------;what	equ 0message	equ what+2when	equ message+4where	equ when+4modif	equ where+4TaskData	equ modif+2TaskMask	equ TaskData+4lastClickWhen	equ TaskMask+4clickCount	equ lastClickWhen+4taskData2	equ clickCount+2taskData3	equ taskData2+4taskData4	equ taskData3+4lastClicky	equ taskData4+4	Y position of last button down.lastClickx	equ lastClicky+2	X position od last button down.exTaskRecSize	equ lastClickx+2;;; --- Event codes ----------------------------------------;inNull	equ $00	No further action required.inButtDwn	equ $01	Button down event.inButtUp	equ $02	Button up event.inKey	equ $03	Key event.inAutoKey	equ $05	Auto-Key event.inUpdate	equ $06	Update event.inActWind	equ $08	Activate window event.inSwitch	equ $09	Switch event.inAccess	equ $0A	Desk Accessory event.inDevice	equ $0B	Device driver event.;;; --- Modifier key flags --------------------------------;K_KEYPAD	equ $2000K_CTL	equ $1000K_OPTION	equ $0800K_CAPSLOCK	equ $0400K_SHIFT	equ $0200K_COMMAND	equ $0100K_BUTT0	equ $0080K_BUTT1	equ $0040K_CHANGE	equ $0002K_ACTIVE	equ $0001;;; --- Window record	header offsets ---------------------------;wNext	equ 0	Pointer to next window, 0=bottom.wPort	equ wNext+4	Window's port.wDefProc	equ wPort+170	Address of window's defProc.wRefCon	equ wDefProc+4	Reserved for application's use.wContDraw	equ wRefCon+4	Address of routine to draw content.wReserved	equ wContDraw+4wStrucRgn	equ wReserved+4	Handle of window's entire region.wContRgn	equ wStrucRgn+4	Handle of window's content region.wUpdateRgn	equ wContRgn+4	Handle of area needing to be redrawn.wControls	equ wUpdateRgn+4	Pointer to controls	in window.wFrameCtls	equ wControls+4	Pointer to controls	in frame.wFrame	equ wFrameCtls+4	Type of window, frame flags.WHEADERSIZE	equ wFrame+2	Size of window record header.;;; --- Flag masks for wkind ------------------------------;W_SYSTEM	equ $8000	1 = system window.;;; --- Window Frame Type Masks ----------------------;F_TITLE	equ $8000	TRUE = title bar.F_CLOSE	equ $4000	TRUE = close box.F_ALERT	equ $2000F_RSCRL	equ $1000	TRUE = right scroll	bar.F_BSCRL	equ $0800	TRUE = bottom scroll bar.F_GROW	equ $0400	TRUE = grow box.F_FLEX	equ $0200	TRUE = don't change origin.F_ZOOM	equ $0100	TRUE = zoom box.F_MOVE	equ $0080	TRUE = allow move on title bar.F_QCONTENT	equ $0040	TRUE = reuse button	in content.F_VIS	equ $0020	TRUE = window is visible.F_INFO	equ $0010	TRUE = content inset from left side.F_CTL_TIE	equ $0008	FALSE= control state tied to window'sF_ALLOCATE	equ $0004	TRUE = window record allocated by me.F_ZOOMED	equ $0002	TRUE = window is full.F_HILITED	equ $0001	TRUE = frame is highlighted.;;; ------ AND masks --------------;_F_TITLE	equ $7FFF_F_CLOSE	equ $BFFF_F_ALERT	equ $DFFF_F_RSCRL	equ $EFFF_F_BSCRL	equ $F7FF_F_GROW	equ $FBFF_F_ZOOM	equ $FEFF_F_MOVE	equ $FF7F_F_QCONTENT	equ $FFBF_F_VIS	equ $FFDF_F_INFO	equ $FFEF_F_CTL_TIE	equ $FFF7_F_ALLOCATE	equ $FFFB_F_ZOOMED	equ $FFFD_F_HILITED	equ $FFFE;;; --- Window Manager's Tool number -----------------------------;WindToolNum	equ 14;;; --- Variation code, command to window	definition procedure ----------;wDraw	equ 0	Draw window's frame.wHit	equ 1	Tell what region given point is in.wCalcRgns	equ 2	Calculate wstrucRgn	and wcontRgn.wNew	equ 3	Do any additional initialization.wDispose	equ 4	Take any additional	disposal actions.wGetDrag	equ 5	Get routine to draw	window outline.wGrowFrame	equ 6	Draw window's grow image.wRecSize	equ 7	Return size of additional record space.wPosition	equ 8	Return new window's portRect.wBehind	equ 9	Return where in list to insert new window.wCallDefProc	equ 10	Generic call to defProc.;;; --- wCallDefProc request numbers ---------------------------;wSetOrgMask	equ 0wSetMaxGrow	equ 1wSetScroll	equ 2wSetPage	equ 3wSetInfoRefCon	equ 4wSetInfoDraw	equ 5wSetOrigin	equ 6wSetDataSize	equ 7wSetZoomRect	equ 8wSetTitle	equ 9wSetColorTable	equ 10wSetFrameFlag	equ 11wGetOrgMask	equ 12wGetMaxGrow	equ 13wGetScroll	equ 14wGetPage	equ 15wGetInfoRefCon	equ 16wGetInfoDraw	equ 17wGetOrigin	equ 18wGetDataSize	equ 19wGetZoomRect	equ 20wGetTitle	equ 21wGetColorTable	equ 22wGetFrameFlag	equ 23wGetInfoRect	equ 24wDrawInfo	equ 25wStartInfoDraw	equ 26wEndInfoDraw	equ 27wZoomWindow	equ 28wStartDrawing	equ 29wStartMove	equ 30wStartGrow	equ 31wNewSize	equ 32wTask	equ 33;;; --- Hit return flags ---------------------------------------;Null	equ $0000wInDesk	equ $0010	On Desktop.wInMenuBar	equ $0011	On System Menu Bar.wClickCalled	equ $0012	SystemClick called (returned only as action).winContent	equ $0013	In content region.wInDrag	equ $0014	In drag region.wInGrow	equ $0015	In grow region, active window only.wInGoAway	equ $0016	In go-away region, active window only.wInZoom	equ $0017	In zoom region, active window only.wInInfo	equ $0018	In information bar.wInSpecial	equ $0019	Item ID selected was 250-255.wInDeskItem	equ $001A	Item ID selected was 1-249.wInFrame	equ $001B	In frame, but not on anything else.wInactMenu	equ $001C	Inactive menu item selected.wClosedNDA	equ $001D	Desk accessory closed (returned only as	action).wCalledSysEdit	equ $001E	SystemEdit called (returned only as action).wTrackZoom	equ $001F	Zoom box clicked, but not selected (action only).wHitFrame	equ $0020	Button down on frame, made active (action only).wInControl	equ $0021wInControlMenu	equ $0022	Control took the menu item (action only)wNotInModal	equ $0023;;; --- TaskMaster feature masks -------------------------------;TM_MENUKEY	equ $00000001	0TM_UPDATE	equ $00000002	1TM_FINDW	equ $00000004	2TM_MENUSLT	equ $00000008	3TM_OPENNDA	equ $00000010	4TM_SYSCLK	equ $00000020	5TM_DRAGW	equ $00000040	6TM_CONTENT	equ $00000080	7TM_CLOSE	equ $00000100	8TM_ZOOM	equ $00000200	9TM_GROW	equ $00000400	10TM_SCROLL	equ $00000800	11TM_SPECIAL	equ $00001000	12TM_CREDRAW	equ $00002000	13TM_INACTIVE	equ $00004000	14TM_INFO	equ $00008000	15;;; --- Window Manager Error Codes.;paramLenErr	equ $0E01allocateErr	equ $0E02taskMaskErr	equ $0E03compileTooLarge	equ $0E04cantUpdateErr	equ $0E05	;new for UpdateWindow, 19-Jun-92 DAL;;; --- Color indexes	into color table ---------------------------;BLACK	equ $0000WHITE	equ $FFFF;; --- Window frame pattern types -------------------------------;P_SOLID	equ $0000P_DITHER	equ $0100P_DOTTED	equ $0200P_LINED	equ $0300;;;; --- Control record offsets -----------------------------------;CtlNext	equ 0CtlOwner	equ CtlNext+4CtlRect	equ CtlOwner+4CtlFlag	equ CtlRect+RECTSIZECtlHilite	equ CtlFlag+1CtlValue	equ CtlHilite+1CtlProc	equ CtlValue+2CtlAction	equ CtlProc+4CtlData	equ CtlAction+4CtlrefCon	equ CtlData+4CtlColor	equ CtlrefCon+4ThumbRect	equ CtlColor+4PageRegion	equ ThumbRect+RECTSIZECtlRecSize	equ CtlColor+4;;; --- CtlFlag bit flags --------------------;C_HILITE	equ $00FF	Hilited part, 255 =	inactive.UP_FLAG	equ $0001	Up arrow.DOWN_FLAG	equ $0002	Down arrow.LEFT_FLAG	equ $0004	Left arrow.RIGHT_FLAG	equ $0008	Right arrow.DIR_SCROLL	equ $0010	0 = vertical, 1 = horizontal scroll.CTL_INVIS	equ $0080	1 if control is invisible.;;; --- Part codes for standard controls -----------------;BUTT_PART	equ 2CHECK_PART	equ 3UP_PART	equ 5DOWN_PART	equ 6UPP_PART	equ 7DOWNP_PART	equ 8GROW_PART	equ 10THUMB_PART	equ 129;;;; = = = = = = = = =	= = = = = = =;          Dynamic RAM.; = = = = = = = = =	= = = = = = =;;; --- Offsets into Window Manager global data ----------------;lineW	equ 0	WORD - Width of lines.titleHeight	equ lineW+2	WORD - Height of title bar.titleYPos	equ titleHeight+2	WORD - Y position of title in title bar.closeHeight	equ titleYPos+2	WORD - Height of close and zoom boxes.closeWidth	equ closeHeight+2	WORD - Width of close and zoom boxes.defWindClr	equ closeWidth+2	LONG - Pointer to default color table.windIconFont	equ defWindClr+4	LONG - Handle of window icon font.screenMode	equ windIconFont+4	WORD - TRUE if 640 mode, FALSE if 320.pattern	equ screenMode+2	BYTE[32] - Pattern buffer.callerDpage	equ pattern+32	WORDcallerDataB	equ callerDpage+2	WORD;;; --- Rest of data area not global ---------------------------;scrn2scrn	equ callerDataB+2	BYTES[22] - Paint pixels parameter block.hiflag	equ scrn2scrn+22	WORDjustInfo	equ hiflag+2	WORDmyevent	equ justInfo+2	BYTE[16] - Internal	event record.scInfo	equ myevent+16	BYTE[8]screen	equ scInfo+8	BYTE[8]LocInfo1	equ screen+8	LOCINFOdrag_bound	equ LocInfo1+16	RECTslop_bound	equ drag_bound++8	RECTwmgr_wind	equ slop_bound+8	LONG         Make Window Manager portport	equ wmgr_wind+4	BYTE[270]    look like a window record.fontHandle	equ port+270	BYTE[6] - Fake handle for icon font.WindGlobal	equ fontHandle+6	WORD - Global flag:;		        bit 0=1 to turn hiliting off.iconNum	equ WindGlobal+2	WORD - Temp work space for icon number.TaskAction	equ iconNum+2	WORD - Action that Task Master performed.blitsrc	equ TaskAction+2	RECTblitdes	equ blitsrc+8	RECTtaskRequest	equ blitdes+8	WORDcallProcList	equ taskRequest+2	BYTE[10] - table passed to defProc.foundFCtl	equ callProcList+10	LONG - handle of found scroll bar.DATaskFlag	equ foundFCtl+4	WORD - flag for task master so DA's can use it.WindTitle	equ DATaskFlag+2	BYTES[32] - Used to hold window's title;RAMSIZE	equ WindTitle+255	Size of RAM data block.;-----------------------------------------------------------;; New task master bits;tmContentControls	equ $0001tmControlKey	equ $0002tmControlMenu	equ $0004tmMultiClick	equ $0008tmIdleEvents	equ $0010tmNoGetNextEvent	equ $0020tmModalWindow	equ $0040;-----------------------------------------------------------;; Extended task record def;NewTaskRecord	Record 0taskWhat   	ds.W 1	EQU   $00 ; Word - WmTaskRec -  taskMessage   	ds.L 1	EQU   $02 ; Long - WmTaskRec -  taskWhen   	ds.L 1	EQU   $06 ; Long - WmTaskRec -  taskWhere   	ds.L 1	EQU   $0A ; Point - WmTaskRec -  taskModifiers   	ds.W 1	EQU   $0E ; Word - WmTaskRec -  taskData   	ds.L 1	EQU   $10 ; Long - WmTaskRec - TaskMaster return value.taskMask   	ds.L 1	EQU   $14 ; Long - WmTaskRec - TaskMaster feature mask.taskLastClick	ds.L 1taskClickCount	ds.W 1taskData2	ds.L 1taskData3	ds.L 1taskData4	ds.L 1	ENDR